from __future__ import annotations

from pathlib import Path

from fastapi import APIRouter
from fastapi.responses import HTMLResponse

router = APIRouter(tags=["dashboard"])

ATLAS_LOGO_B64 = Path(__file__).with_name("atlas_logo.b64").read_text(encoding="utf-8-sig").strip()


def dashboard_view() -> HTMLResponse:
    return HTMLResponse(DASHBOARD_HTML.replace(
        "</body>", '<script src="/ui/preferences.js"></script></body>'))


DASHBOARD_HTML = r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>ATLAS Live Trading Intelligence</title>
<style>
:root{color-scheme:dark;--bg:#080b10;--panel:#0f141c;--panel2:#151b24;--line:#4a3b18;--gold:#f4c542;--gold2:#ffdf73;--text:#f7f0d8;--muted:#9c9276;--green:#46d68c;--red:#ff6b75}*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:radial-gradient(circle at 60% -20%,#2c2410 0,#080b10 38%,#05070a 100%);color:var(--text);font:14px 'Rajdhani',Inter,'Segoe UI',Arial,sans-serif}button,input,select{font:inherit}.atlas-shell{min-height:100vh;display:grid;grid-template-columns:92px minmax(0,1fr)}.side-nav{position:sticky;top:0;height:100vh;border-right:1px solid #2e2818;background:#080b10dd;padding:18px 10px;display:flex;flex-direction:column;align-items:center;gap:12px}.side-logo{width:54px;height:54px;border-radius:15px;object-fit:cover;border:1px solid var(--gold);margin-bottom:18px}.nav-item{width:70px;padding:11px 6px;border-radius:12px;color:var(--muted);text-align:center;text-decoration:none;font-size:11px}.nav-item.active,.nav-item:hover{background:#f4c54214;color:var(--gold)}.nav-icon{display:block;font-size:20px;margin-bottom:5px}.workspace{min-width:0;padding:18px 22px 28px}.topbar{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:16px}.brandline{display:flex;align-items:center;gap:12px}.mobile-logo{display:none;width:42px;height:42px;border-radius:12px;border:1px solid var(--gold);object-fit:cover}.brand-title{font-size:28px;letter-spacing:.12em;color:var(--gold);font-weight:900}.status-row,.actions{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.chip{padding:8px 11px;border-radius:999px;border:1px solid #51441f;color:var(--gold);font-weight:800;font-size:11px}.chip.ok{border-color:#1b7449;color:var(--green)}.btn,.trade-btn{border:1px solid #6a551d;background:#151109;color:var(--gold);border-radius:11px;padding:10px 14px;font-weight:800;cursor:pointer}.btn.primary,.trade-btn.primary{background:var(--gold);color:#171205;border-color:var(--gold)}.btn:hover,.trade-btn:hover{filter:brightness(1.08)}.card{background:linear-gradient(180deg,#111720,#0b1017);border:1px solid #302914;border-radius:16px;padding:14px;box-shadow:0 18px 45px #0005}.label{color:var(--muted);font-size:10px;text-transform:uppercase;letter-spacing:.11em;font-weight:800}.big{color:var(--gold2);font-size:22px;font-weight:900;margin-top:5px}.mini{color:var(--muted);font-size:11px}.green{color:var(--green)!important}.red{color:var(--red)!important}.yellow{color:var(--gold)!important}.insight-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin-bottom:10px}.insight{min-height:86px}.chart-workspace{padding:14px;margin-bottom:10px;background:linear-gradient(180deg,#111720,#0b1017);border:1px solid #302914;border-radius:16px;box-shadow:0 18px 45px #0005}.chart-head{display:flex;justify-content:space-between;gap:12px;align-items:center}.chart-controls{display:flex;gap:8px;align-items:center}.chart-controls select{width:auto;min-width:88px}.chart{width:100%;height:300px;background:#080b10;border:1px solid #282417;border-radius:12px;margin-top:12px}.stats{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px;margin-bottom:10px}.compact-panels{display:grid;grid-template-columns:1.2fr .8fr;gap:10px;margin-bottom:10px}.form-grid{display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px;margin-top:10px}select,input{width:100%;background:#090d13;color:var(--text);border:1px solid #3b321b;border-radius:10px;padding:10px}.secondary-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:10px}.row{display:grid;grid-template-columns:1.2fr .8fr .6fr .6fr .6fr;gap:8px;padding:9px 0;border-bottom:1px solid #262217}.pos,.market{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;padding:8px 0;border-bottom:1px solid #262217}.tag{border:1px solid #54451d;border-radius:999px;padding:3px 7px;color:var(--gold);font-size:10px}.story{display:block;color:var(--text);text-decoration:none;padding:9px 0;border-bottom:1px solid #262217}.empty{color:var(--muted);padding:8px 0}.quote{display:flex;align-items:baseline;gap:10px;margin-top:8px}.price{font-size:28px;font-weight:900;color:var(--gold)}.trade-actions,.bottom-actions{display:flex;gap:8px}.demo-position{border:1px dashed #3d341d;border-radius:10px;padding:10px;margin-top:10px}.demo-only,.notice{font-size:10px;color:var(--muted)}.bottom-actions{position:sticky;bottom:10px;margin-top:14px;padding:9px;border:1px solid #3b3219;border-radius:14px;background:#080b10ee;backdrop-filter:blur(10px);z-index:5}.bottom-actions .btn{flex:1}.desktop-only{display:block}
@media(max-width:1050px){.atlas-shell{grid-template-columns:78px minmax(0,1fr)}.side-nav{padding-left:4px;padding-right:4px}.stats{grid-template-columns:repeat(3,minmax(0,1fr))}.compact-panels,.secondary-grid{grid-template-columns:1fr}}
@media(max-width:760px){.atlas-shell{display:block}.side-nav{display:none}.workspace{padding:12px 10px 90px}.mobile-logo{display:block}.brand-title{font-size:22px}.topbar{align-items:flex-start}.status-row{justify-content:flex-end}.insight-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.stats{grid-template-columns:repeat(2,minmax(0,1fr))}.form-grid{grid-template-columns:1fr}.chart{height:260px}.chart-head{align-items:flex-start;flex-direction:column}.compact-panels,.secondary-grid{grid-template-columns:1fr}.row{grid-template-columns:1fr 1fr}.pos,.market{grid-template-columns:1fr 1fr}.bottom-actions{position:fixed;left:10px;right:10px;bottom:10px}.desktop-only{display:none}}
</style></head><body><div class="atlas-shell"><aside class="side-nav"><img class="side-logo" src="data:image/webp;base64,__ATLAS_LOGO_B64__" alt="ATLAS"><a class="nav-item active" href="#atlasAiChart"><span class="nav-icon">⌂</span>Home</a><a class="nav-item" href="#marketBoard"><span class="nav-icon">⌁</span>Markets</a><a class="nav-item" href="#demoExecutivePanel"><span class="nav-icon">▶</span>Demo</a><a class="nav-item" href="#mt5Activity"><span class="nav-icon">◫</span>Activity</a></aside><main class="workspace" aria-label="Private ATLAS Dashboard">
<header class="topbar"><div class="brandline"><img id="atlasLogo" class="mobile-logo" src="data:image/webp;base64,__ATLAS_LOGO_B64__" alt="ATLAS"><div><div class="brand-title">ATLAS</div><div class="mini">Trading Intelligence</div></div></div><div class="status-row"><span class="chip" id="planBadge">Demo</span><span class="chip ok" id="status">CONNECTING</span><span class="chip">SIM</span><form method="post" action="/logout" class="desktop-only"><button class="btn" type="submit">Logout</button></form></div></header>
<section class="insight-grid"><div class="card insight" aria-label="AI Trend"><div class="label">Trend</div><div class="big" id="aiTrend">NEUTRAL</div></div><div class="card insight" aria-label="AI Signal"><div class="label">Signal</div><div class="big" id="aiSignal">OBSERVE</div></div><div class="card insight" aria-label="AI Momentum"><div class="label">Bias</div><div class="big" id="aiMomentum">?</div></div><div class="card insight" aria-label="AI Confidence"><div class="label">Conf</div><div class="big" id="aiConfidence">?</div></div></section>
<section class="chart-workspace" id="atlasAiChart" aria-label="AI Chart"><div class="chart-head"><div class="chart-controls"><select id="assetSelect"></select><select id="aiTimeframe"><option value="12">M5</option><option value="24">M15</option><option value="40" selected>H1</option></select></div><div class="quote"><span class="price" id="assetPrice">—</span><span id="assetMove" class="mini">—</span></div></div><svg id="priceChart" class="chart" viewBox="0 0 600 170" preserveAspectRatio="none"><polyline id="priceLine" fill="none" stroke="#f4c542" stroke-width="3" points=""></polyline><polyline id="aiPriceLine" fill="none" stroke="#ff8a24" stroke-width="1.5" opacity=".55" points=""></polyline></svg></section>
<section class="stats"><div class="card"><div class="label">Balance</div><div class="big" id="balance">—</div></div><div class="card"><div class="label">Equity</div><div class="big" id="equity">—</div></div><div class="card"><div class="label">P/L</div><div class="big" id="floating">—</div></div><div class="card"><div class="label">Pos</div><div class="big" id="openPositions">—</div></div><div class="card"><div class="label">Engine</div><div class="big yellow" id="execution">SIMULATION</div></div></section><div id="accountType" style="display:none">—</div>
<section class="compact-panels"><div class="card" id="mt5ConnectPanel"><div class="label">MT5 Demo</div><div class="form-grid"><input id="mt5Login" inputmode="numeric" placeholder="Login"><input id="mt5Server" placeholder="Server"><input id="mt5Password" type="password" autocomplete="current-password" placeholder="Password"></div><div class="actions" style="margin-top:8px"><button class="btn primary" id="connectMt5FxPro" type="button">Connect</button><button class="btn" id="disconnectMt5FxPro" type="button">Disconnect</button></div><div id="mt5ConnectStatus" class="mini" style="margin-top:8px">DEMO only</div></div><div class="card" id="demoExecutivePanel"><div class="label">Demo Engine</div><div id="executiveStatus" class="big">READY</div><div class="actions" style="margin-top:8px"><button class="btn primary" id="startExecutive" type="button">Start</button><button class="btn" id="stopExecutive" type="button">Stop</button></div></div></section>
<section class="secondary-grid"><div class="card" id="mt5Activity"><div class="label">Activity</div><div class="mini" id="accountBadge">No demo</div><div class="actions" style="margin-top:8px"><button class="btn" data-activity-tab="open" type="button">Open</button><button class="btn" data-activity-tab="pending" type="button">Pending</button><button class="btn" data-activity-tab="history" type="button">History</button></div><div id="activityOpen"></div><div id="activityPending" style="display:none"></div><div id="activityHistory" style="display:none"></div></div><div class="card"><div class="label">Account</div><div id="account"></div><div class="label" style="margin-top:10px">Positions</div><div id="positions"></div></div></section>
<section class="secondary-grid"><div class="card"><div class="label">Signals</div><div id="signals"></div></div><div class="card"><div class="label">Demo Trade</div><div class="big" id="tradePrice">—</div><div class="trade-actions" style="margin-top:8px"><button class="trade-btn" data-demo-action="BUY">Buy</button><button class="trade-btn" data-demo-action="SELL">Sell</button></div><div id="demoPosition" class="demo-position"><div class="empty">No position</div></div><button id="closeDemo" class="trade-btn" style="display:none;margin-top:8px">Close</button><div class="demo-only">Simulation only</div></div></section>
<section class="secondary-grid"><div class="card"><div class="label">Markets</div><div id="marketBoard"></div></div><div class="card"><div class="label">News</div><div id="headlines"></div></div></section><div class="notice" id="disclaimer">Demo simulation</div><div class="bottom-actions"><button class="btn primary" type="button" onclick="document.getElementById('mt5ConnectPanel').scrollIntoView({behavior:'smooth'})">Connect</button><button class="btn" type="button" onclick="document.getElementById('startExecutive').click()">Start</button><button class="btn" type="button" onclick="document.getElementById('marketBoard').scrollIntoView({behavior:'smooth'})">Markets</button></div></main></div>
<script>
const priceHistory={},assetMap={};let currentAsset='',lastPrice=null,demoPosition=null;
function el(id){return document.getElementById(id)}function esc(value){return String(value==null?'':value).replace(/[&<>'"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]})}function money(value,currency){if(value==null)return 'PRIVATE';return Number(value).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})+(currency?' '+currency:'')}function tone(value){return Number(value)>=0?'green':'red'}
function currentLanguage(){try{return localStorage.getItem('atlas-language')==='ar'?'ar':'en'}catch(e){return 'en'}}
window.addEventListener('storage',function(e){if(e.key==='atlas-language')refreshBriefing()});document.addEventListener('change',function(e){if(e.target&&e.target.id==='atlas-lang')setTimeout(refreshBriefing,0)});
function signalRow(x){const d=x.decision||{},q=x.quality||{};return '<div class="row"><div><b>'+esc(x.canonical_symbol||x.symbol)+'</b><div class="mini"><span>'+esc(x.asset_class||'')+'</span> · <span>'+esc(x.symbol)+'</span></div></div><div><span class="tag">'+esc(d.bias||'OBSERVE')+'</span><div class="mini">'+esc(d.decision||'OBSERVE')+'</div></div><div><b>'+Number(d.score||0).toFixed(1)+'</b><div class="mini">score</div></div><div><b>'+Number(q.execution_confidence||0).toFixed(1)+'%</b><div class="mini">confidence</div></div><div><b>'+Number(x.opportunity_score||0).toFixed(0)+'</b><div class="mini">opportunity</div></div></div>'}
function updateAssetOptions(symbols){const select=el('assetSelect'),wanted=currentAsset||select.value;symbols.forEach(x=>assetMap[x.canonical_symbol||x.symbol]=x);const names=symbols.map(x=>x.canonical_symbol||x.symbol);if(select.options.length!==names.length||names.some((n,i)=>!select.options[i]||select.options[i].value!==n)){select.innerHTML=names.map(n=>'<option value="'+esc(n)+'">'+esc(n)+'</option>').join('')}currentAsset=names.includes(wanted)?wanted:(names[0]||'');select.value=currentAsset}
function drawChart(name,price){if(!name||!Number.isFinite(price))return;const history=priceHistory[name]||(priceHistory[name]=[]);if(!history.length||history[history.length-1]!==price)history.push(price);if(history.length>40)history.shift();if(history.length<2){el('priceLine').setAttribute('points','0,85 600,85');return}const min=Math.min(...history),max=Math.max(...history),span=(max-min)||1;const pts=history.map((p,i)=>{const x=i*(600/(history.length-1)),y=155-((p-min)/span)*140;return x.toFixed(1)+','+y.toFixed(1)}).join(' ');el('priceLine').setAttribute('points',pts)}

function updateAiChart(){const history=(priceHistory[currentAsset]||[]).slice(-Number(el('aiTimeframe').value||40));if(history.length<2){el('aiPriceLine').setAttribute('points','0,85 600,85');el('aiTrend').textContent='NEUTRAL';el('aiMomentum').textContent='?';el('aiSignal').textContent='OBSERVE';el('aiConfidence').textContent='?';return}const min=Math.min(...history),max=Math.max(...history),span=(max-min)||1;const pts=history.map((p,i)=>{const x=i*(600/(history.length-1)),y=155-((p-min)/span)*140;return x.toFixed(1)+','+y.toFixed(1)}).join(' ');el('aiPriceLine').setAttribute('points',pts);const delta=history[history.length-1]-history[0],trend=delta>0?'BULLISH':delta<0?'BEARISH':'NEUTRAL';el('aiTrend').textContent=trend;el('aiMomentum').textContent=Math.abs(delta).toFixed(6);el('aiSignal').textContent='OBSERVE';el('aiConfidence').textContent=Math.min(100,Math.round((history.length/40)*100))+'%'}
function updateAssetViewer(){const item=assetMap[currentAsset];if(!item)return;const price=Number(item.price||0);const previous=lastPrice;lastPrice=price;el('assetPrice').textContent=price.toLocaleString(undefined,{maximumFractionDigits:6});el('tradePrice').textContent=el('assetPrice').textContent;const move=previous==null?0:price-previous;el('assetMove').textContent=move===0?'—':(move>0?'▲ ':'▼ ')+Math.abs(move).toFixed(6);el('assetMove').className='mini '+(move>=0?'green':'red');drawChart(currentAsset,price);updateAiChart();renderDemoPosition(price)}
function demoTrade(side){const item=assetMap[currentAsset];if(!item)return;demoPosition={side:side,symbol:currentAsset,entry:Number(item.price||0),openedAt:Date.now()};renderDemoPosition(demoPosition.entry)}
function renderDemoPosition(currentPrice){if(!demoPosition){el('demoPosition').innerHTML='<div class="empty">No demo position open.</div>';el('closeDemo').style.display='none';return}const entry=demoPosition.entry,current=Number(currentPrice||entry),direction=demoPosition.side==='BUY'?1:-1,pct=entry?direction*((current-entry)/entry)*100:0;el('demoPosition').innerHTML='<div><b><span>'+esc(demoPosition.side)+'</span> · <span>'+esc(demoPosition.symbol)+'</span></b></div><div class="mini">Entry</div><div>'+entry.toLocaleString(undefined,{maximumFractionDigits:6})+'</div><div class="mini">Current Price</div><div>'+current.toLocaleString(undefined,{maximumFractionDigits:6})+'</div><div class="mini">Demo P/L</div><div class="'+tone(pct)+'"><b>'+pct.toFixed(3)+'%</b></div>';el('closeDemo').style.display='inline-block'}
function activityRow(item,isHistory){const price=isHistory?item.price:item.price_open;return '<div class="pos"><div><b>'+esc(item.symbol||'—')+'</b><div class="mini">'+esc(item.direction||'')+'</div></div><div>'+esc(item.volume??'—')+'</div><div>'+esc(price??'—')+'</div><div class="'+tone(item.profit||0)+'"><b>'+(isHistory?Number(item.profit||0).toFixed(2):esc(item.profit??''))+'</b></div></div>'}
function renderActivity(data,account){el('accountBadge').textContent=account&&account.account_masked?[account.account_type,account.server,account.account_masked].filter(Boolean).join(' · '):'No MT5 Demo connected';el('activityOpen').innerHTML=(data.positions||[]).map(x=>activityRow(x,false)).join('')||'<div class="empty">No open positions.</div>';el('activityPending').innerHTML=(data.pending_orders||[]).map(x=>activityRow(x,false)).join('')||'<div class="empty">No pending orders.</div>';el('activityHistory').innerHTML=(data.recent_trades||[]).map(x=>activityRow(x,true)).join('')||'<div class="empty">No recent trades.</div>'}
document.querySelectorAll('[data-activity-tab]').forEach(btn=>btn.addEventListener('click',()=>{const target=btn.dataset.activityTab;['open','pending','history'].forEach(name=>{el('activity'+name[0].toUpperCase()+name.slice(1)).style.display=name===target?'block':'none'})}));
async function refreshExecutive(){const status=el('executiveStatus');try{const r=await fetch('/api/demo-executive/status',{cache:'no-store'}),d=await r.json();status.textContent=d.active?'DEMO EXECUTIVE ACTIVE':'DEMO EXECUTIVE READY'}catch(e){status.textContent='Demo Executive unavailable.'}}
async function connectMt5FxProDemo(){const login=Number(el('mt5Login').value),server=el('mt5Server').value.trim(),password=el('mt5Password').value;if(!Number.isInteger(login)||!server||!password){el('mt5ConnectStatus').textContent='Enter DEMO login, server, and password.';return}el('mt5ConnectStatus').textContent='Connecting DEMO account…';try{const r=await fetch('/api/mt5-demo/connect',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({login:login,password:password,server:server,broker:'FxPro'})});const d=await r.json();el('mt5Password').value='';el('mt5ConnectStatus').textContent=r.ok?('CONNECTED · '+(d.account_masked||'DEMO')):(d.detail||'Connection rejected');if(r.ok)refresh()}catch(e){el('mt5Password').value='';el('mt5ConnectStatus').textContent='Connection unavailable.'}}
async function disconnectMt5FxProDemo(){const r=await fetch('/api/mt5-demo/disconnect',{method:'POST'});el('mt5ConnectStatus').textContent=r.ok?'DISCONNECTED':'Disconnect unavailable';if(r.ok)refresh()}
el('connectMt5FxPro').addEventListener('click',connectMt5FxProDemo);el('disconnectMt5FxPro').addEventListener('click',disconnectMt5FxProDemo);
el('startExecutive').addEventListener('click',async()=>{const r=await fetch('/api/demo-executive/start',{method:'POST'});const d=await r.json();el('executiveStatus').textContent=r.ok?('SIMULATION: '+(d.decision||'WAIT')):(d.detail||'Unavailable')});
el('stopExecutive').addEventListener('click',async()=>{const r=await fetch('/api/demo-executive/stop',{method:'POST'});el('executiveStatus').textContent=r.ok?'DEMO EXECUTIVE STOPPED':'Unavailable'});
el('assetSelect').addEventListener('change',e=>{currentAsset=e.target.value;lastPrice=null;updateAssetViewer()});el('aiTimeframe').addEventListener('change',updateAiChart);document.querySelectorAll('[data-demo-action]').forEach(btn=>btn.addEventListener('click',()=>demoTrade(btn.dataset.demoAction)));el('closeDemo').addEventListener('click',()=>{demoPosition=null;renderDemoPosition(0)});
async function refresh(){try{const response=await fetch('/api/user/dashboard',{cache:'no-store'});if(response.status===401){location.replace('/login');return}if(!response.ok)throw Error('offline');const payload=await response.json(),data=payload.mt5||{},account=data.account||{},symbols=data.symbols||[];el('planBadge').textContent=payload.plan||'FREE';el('status').textContent=data.connected?'DEMO CONNECTED':'NOT CONNECTED';el('accountType').textContent=account.account_type||'—';el('accountType').className='big yellow';el('equity').textContent=money(account.equity,account.currency);el('balance').textContent=money(account.balance,account.currency);el('floating').textContent=money(data.floating_position_pnl,account.currency);el('floating').className='big '+tone(data.floating_position_pnl);el('openPositions').textContent=data.open_positions||0;el('execution').textContent='SIMULATION';el('account').innerHTML=account.account_masked?'<div class="pos"><span>'+esc(account.broker||'MT5')+'</span><b>'+esc(account.account_masked)+'</b><span>'+esc(account.server)+'</span><b>DEMO</b></div>':'<div class="empty">Connect your MT5 Demo account.</div>';el('signals').innerHTML=symbols.map(signalRow).join('')||'<div class="empty">No markets available.</div>';el('positions').innerHTML=(data.positions||[]).map(p=>activityRow(p,false)).join('')||'<div class="empty">No open positions.</div>';renderActivity(data,account);refreshExecutive();updateAssetOptions(symbols);updateAssetViewer()}catch(error){el('status').textContent='OFFLINE'}}
async function refreshBriefing(){try{const language=currentLanguage(),response=await fetch('/dashboard/market-briefing?language='+encodeURIComponent(language),{cache:'no-store'}),data=await response.json();if(!response.ok)throw Error('unavailable');el('marketBoard').innerHTML=(data.market_board||[]).map(x=>'<div class="market"><div><b>'+esc(x.label)+'</b><div class="mini">'+esc(x.category)+'</div></div><b>'+(x.price==null?'—':Number(x.price).toLocaleString())+'</b><b class="'+tone(x.change_percent)+'">'+(x.change_percent==null?'—':Number(x.change_percent).toFixed(2)+'%')+'</b><span class="tag">'+esc(x.market_state)+'</span></div>').join('')||'<div class="empty">Market data temporarily unavailable.</div>';el('headlines').innerHTML=(data.headlines||[]).map(x=>'<a class="story" href="'+esc(x.url)+'" target="_blank" rel="noopener"><b>'+esc(x.title)+'</b><div class="mini">'+esc(x.source)+' · '+esc(x.published_at)+'</div></a>').join('')||'<div class="empty">Financial headlines temporarily unavailable.</div>'}catch(error){el('marketBoard').innerHTML='<div class="empty">Market board unavailable.</div>';el('headlines').innerHTML='<div class="empty">Headlines unavailable.</div>'}}
refresh();refreshBriefing();setInterval(refresh,5000);setInterval(refreshBriefing,60000);
</script></body></html>'''

DASHBOARD_HTML = DASHBOARD_HTML.replace("__ATLAS_LOGO_B64__", ATLAS_LOGO_B64)
